import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
  // Arrange: a draft vendor whose only document is an extracted w9
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Missing Docs"), category: "services", contact_email: "missing-docs@example.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const { id: vendorId } = (await created.json()) as { id: string };

  const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);

  // Extraction runs in the background; wait until the w9 is extracted.
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendorId}/documents`);
      const docs = (await res.json()) as { kind: string; status: string }[];
      return docs.find((d) => d.kind === "w9")?.status;
    }, { message: "w9 extraction finishes", timeout: 60_000 })
    .toBe("extracted");

  // Act
  const response = await member.post(`/api/vendors/${vendorId}/submit`);

  // Assert
  const body = await response.text();
  expect(response.status(), body).toBe(409);
  const error = (JSON.parse(body) as { error: { code: string } }).error;
  expect(error.code, body).toBe("documents_incomplete");
  expect(body).toContain("contract");
  expect(body).toContain("insurance_certificate");
  expect(body).not.toContain("\"w9\",\"");
});
